//	ArgList = Arg { comma Arg } .
//
//	State 0
//		on  at, bang, colon, color, elem_ref, ellipsis, float_lit, ident, int_lit, kw_false, kw_func, kw_null, kw_true, lbrace, lbracket, lparen, minus, raw_str, string_lit, triple_str, unit_lit
